  $$[{"id":"A","code":"A","name":"Alfa","category":"flags","pt":"Tenho um mergulhador na água; conserve-se afastado e a pouca velocidade.","en":"I have a diver down; keep well clear at slow speed."},{"id":"B","code":"B","name":"Bravo","category":"flags","pt":"Carrego, descarrego ou transporto carga perigosa.","en":"I am taking in or discharging or carrying dangerous goods."},{"id":"C","code":"C","name":"Charlie","category":"flags","pt":"Sim (Afirmativo).","en":"Affirmative."},{"id":"D","code":"D","name":"Delta","category":"flags","pt":"Mantenha-se afastado, estou a manobrar com dificuldade.","en":"Keep clear of me; I am maneuvering with difficulty."},{"id":"E","code":"E","name":"Echo","category":"flags","pt":"Estou a guinar para estibordo (EB).","en":"I am altering my course to starboard."},{"id":"F","code":"F","name":"Foxtrot","category":"flags","pt":"Estou com avaria; comunique comigo.","en":"I am disabled; communicate with me."},{"id":"G","code":"G","name":"Golf","category":"flags","pt":"Necessito de um piloto.","en":"I require a pilot."},{"id":"H","code":"H","name":"Hotel","category":"flags","pt":"Tenho piloto a bordo.","en":"I have a pilot on board."},{"id":"I","code":"I","name":"India","category":"flags","pt":"Estou a guinar para bombordo (BB).","en":"I am altering my course to port."},{"id":"J","code":"J","name":"Juliet","category":"flags","pt":"Estou com incêndio a bordo: mantenha-se afastado.","en":"I am going to send a message by semaphore.","note":"O material-base fornecido apresenta significados PT e EN divergentes para a bandeira J."},{"id":"K","code":"K","name":"Kilo","category":"flags","pt":"Tenho uma comunicação a fazer.","en":"I wish to communicate with you."},{"id":"L","code":"L","name":"Lima","category":"flags","pt":"Você deve parar sua embarcação imediatamente.","en":"At sea: You should stop your vessel instantly.","note":"O material-base também registra, em porto: “The ship is quarantined.”"},{"id":"M","code":"M","name":"Mike","category":"flags","pt":"O meu navio está parado.","en":"My vessel is stopped and making no way through the water."},{"id":"N","code":"N","name":"November","category":"flags","pt":"Não (Negativo).","en":"Negative."},{"id":"O","code":"O","name":"Oscar","category":"flags","pt":"Homem ao mar.","en":"Man overboard."},{"id":"P","code":"P","name":"Papa","category":"flags","pt":"No porto: todas as pessoas devem regressar a bordo pois o navio vai largar. No mar, por embarcações de pesca: minhas redes estão presas numa obstrução.","en":"In harbour: All persons should report on board as the vessel is about to proceed to sea. At sea, by fishing vessels: My nets have come fast upon an obstruction."},{"id":"Q","code":"Q","name":"Quebec","category":"flags","pt":"Peço livre prática (licença para entrar em porto).","en":"My vessel is healthy and I request free pratique."},{"id":"R","code":"R","name":"Romeo","category":"flags","pt":"Sem significado no material-base para o Código Internacional de Sinais.","en":"No meaning is assigned in the supplied study material.","note":"O material-base menciona usos específicos da Marinha Portuguesa fora deste significado CIS."},{"id":"S","code":"S","name":"Sierra","category":"flags","pt":"Estou a fazer marcha a ré a toda a força.","en":"I am operating astern propulsion."},{"id":"T","code":"T","name":"Tango","category":"flags","pt":"Mantenha-se afastado. Em embarcações de pesca: mantenha-se afastado; estou empenhado em arrasto de parelha.","en":"Keep clear of me. Fishing boats: Keep clear of me; I am engaged in pair trawling."},{"id":"U","code":"U","name":"Uniform","category":"flags","pt":"Vai sobre um perigo.","en":"You are running into danger."},{"id":"V","code":"V","name":"Victor","category":"flags","pt":"Peço assistência.","en":"I require assistance."},{"id":"W","code":"W","name":"Whiskey","category":"flags","tags":["medical"],"pt":"Peço assistência médica.","en":"I require medical assistance."},{"id":"X","code":"X","name":"Xray","category":"flags","pt":"Pare as suas manobras.","en":"Stop carrying out your intentions and watch for my signals."},{"id":"Y","code":"Y","name":"Yankee","category":"flags","pt":"Estou a garrar (arrastar a âncora).","en":"I am dragging my anchor."},{"id":"Z","code":"Z","name":"Zulu","category":"flags","pt":"Peço reboque.","en":"I require a tug.","note":"O material-base também registra uso por embarcações de pesca próximo aos pesqueiros: “I am shooting nets.”"},{"id":"AC","code":"AC","name":"","category":"combinations","pt":"Estou a abandonar o meu navio.","en":"I am abandoning my vessel."},{"id":"AN","code":"AN","name":"","category":"combinations","tags":["medical"],"pt":"Preciso de um médico.","en":"I need a doctor."},{"id":"BR","code":"BR","name":"","category":"combinations","pt":"Necessito de um helicóptero.","en":"I require a helicopter."},{"id":"CD","code":"CD","name":"","category":"combinations","tags":["distress"],"pt":"Peço assistência imediata.","en":"I require immediate assistance."},{"id":"DV","code":"DV","name":"","category":"combinations","pt":"Estou à deriva.","en":"I am drifting."},{"id":"EF","code":"EF","name":"","category":"combinations","tags":["distress"],"pt":"O SOS/MAYDAY encontra-se cancelado.","en":"SOS/MAYDAY is cancelled."},{"id":"FA","code":"FA","name":"","category":"combinations","pt":"Pode fornecer-me a minha posição?","en":"Can you give me my position?"},{"id":"GW","code":"GW","name":"","category":"combinations","tags":["distress"],"pt":"Homem ao mar. Efetue a sua recolha.","en":"Man overboard. Please take action to pick him up."},{"id":"JL","code":"JL","name":"","category":"combinations","tags":["distress"],"pt":"Corre o risco de encalhar.","en":"You are running the risk of going aground."},{"id":"NC","code":"NC","name":"Distress","category":"combinations","tags":["distress"],"pt":"Estou em perigo e peço assistência imediata.","en":"I am in distress and require immediate assistance."},{"id":"PD","code":"PD","name":"","category":"combinations","pt":"As suas luzes de 